-- 2. recipes, with attribution as CC BY-SA requires

with ins as (
  insert into public.recipes
    (title, instructions, cuisine, status, author_id,
     source_name, source_url, license)
  select 'Albanian Fried Meatballs', 'Soak bread in water and squeeze hard to drain.
Combine soaked bread, ground meat, bread crumbs, oil or melted butter, onion, cheese, parsley, salt, pepper, and mint, and mix thoroughly.
Form mixture into 1 inch-thick patties, then sprinkle with salt, pepper, and oregano.
Roll in flour and fry in hot oil.
Serve hot with French fries or mashed potatoes.',
         NULL, 'approved',
         (select id from public.profiles where role = 'admin'
          order by created_at limit 1),
         'Wikibooks Cookbook', 'https://en.wikibooks.org/wiki/Cookbook%3AAlbanian_Fried_Meatballs',
         'CC BY-SA 3.0'
  where not exists (
    select 1 from public.recipes where lower(title) = lower('Albanian Fried Meatballs'))
  returning id
)
insert into public.recipe_ingredients (recipe_id, ingredient_id, role, quantity)
select ins.id, i.id, 'core', v.qty
from ins
join (values
  ('bread', '1 slice'),
  ('meat', '1 lb'),
  ('onions', '1'),
  ('cheese', '2 tablespoons'),
  ('bread', '2 tablespoons'),
  ('oil', '2 tablespoons'),
  ('parsley', '1 tablespoon'),
  ('salt', NULL),
  ('pepper', NULL),
  ('mint', NULL),
  ('oregano', NULL),
  ('flour', '1 cup'),
  ('oil', '1 cup')
) as v(name, qty) on true
join public.ingredients i on lower(i.name) = v.name
on conflict (recipe_id, ingredient_id) do nothing;

with ins as (
  insert into public.recipes
    (title, instructions, cuisine, status, author_id,
     source_name, source_url, license)
  select 'Albanian Meat with Walnuts', 'Place the meat or chicken in a saucepan, and cook over medium heat until tender.
Remove the meat, and set it aside in a dish while leaving the remaining juices in the saucepan.
In another saucepan, add the flour and stir over heat until it becomes light brown in color—do not overcook! Then, add half the butter.
Add the walnuts, garlic, and egg yolks, stirring constantly.
Add the meat juices from the other saucepan, and stir until all the ingredients thicken. Immediately remove from the heat to avoid solidifying the egg yolks. Fold in the meat.
Pan fry the remaining half stick of butter until brown, and pour over the dish before serving.',
         NULL, 'approved',
         (select id from public.profiles where role = 'admin'
          order by created_at limit 1),
         'Wikibooks Cookbook', 'https://en.wikibooks.org/wiki/Cookbook%3AAlbanian_Meat_with_Walnuts',
         'CC BY-SA 3.0'
  where not exists (
    select 1 from public.recipes where lower(title) = lower('Albanian Meat with Walnuts'))
  returning id
)
