with ins as (
  insert into public.recipes
    (title, instructions, cuisine, status, author_id,
     source_name, source_url, license)
  select 'Caramelized Sweet and Sour Onion Marmalade', 'Heat oil in a large frying pan over medium heat. Add onions, and sauté, stirring, for about 15 minutes, or until they begin to brown. Do not cook over high heat, as the outside of the onions will char too quickly before the insides have softened and sweetened.
When onions have softened and turned a light golden brown, add sugar. Continue stirring until sugar melts and begins to bubble.
As the onions turn a richer brown, clear a space in the center of the pan. Pour balsamic vinegar directly onto the hot pan, then stir it into onions.
When vinegar has reduced, leaving a syrupy coating on the onions, turn off the heat.
Stir in salt and pepper, and allow onions to cool.',
         'Italian', 'approved',
         (select id from public.profiles where role = 'admin'
          order by created_at limit 1),
         'Wikibooks Cookbook', 'https://en.wikibooks.org/wiki/Cookbook%3ACaramelized_Sweet_and_Sour_Onion_Marmalade',
         'CC BY-SA 3.0'
  where not exists (
