with ins as (
  insert into public.recipes
    (title, instructions, cuisine, status, author_id,
     source_name, source_url, license)
  select 'Granola', 'Combine all ingredients except the raisins and blueberries.
Spread the mixture on a tray and bake for 1 hour at 250°F, stirring every 10 minutes.
Let cool, then mix in the raisins and blueberries.',
         NULL, 'approved',
         (select id from public.profiles where role = 'admin'
          order by created_at limit 1),
         'Wikibooks Cookbook', 'https://en.wikibooks.org/wiki/Cookbook%3AGranola',
         'CC BY-SA 3.0'
  where not exists (
    select 1 from public.recipes where lower(title) = lower('Granola'))
  returning id
)
insert into public.recipe_ingredients (recipe_id, ingredient_id, role, quantity)
select ins.id, i.id, 'core', v.qty
from ins
join (values
  ('walnuts', NULL),
  ('walnuts', NULL),
  ('almonds', NULL),
  ('sugar', NULL),
  ('olive oil', NULL),
  ('honey', '1½ cup'),
  ('salt', '1 teaspoon'),
  ('rolled oat', '4 cups'),
  ('raisins', NULL)
) as v(name, qty) on true
join public.ingredients i on lower(i.name) = v.name
on conflict (recipe_id, ingredient_id) do nothing;

with ins as (
  insert into public.recipes
    (title, instructions, cuisine, status, author_id,
     source_name, source_url, license)
  select 'Grapefruit and Crab Cocktail', 'Cut the grapefruits in half. Carefully remove and chop the flesh.
Divide the chopped grapefruit between 4 grapefruit hulls or 4 serving glasses
Toss the asparagus tips with the oil, lemon juice and seasoning. Pile on top of the chopped grapefruit, and top each with a little crab.
To decorate, put 1 teaspoon mayonnaise on each portion, and garnish with parsley.',
         NULL, 'approved',
         (select id from public.profiles where role = 'admin'
          order by created_at limit 1),
         'Wikibooks Cookbook', 'https://en.wikibooks.org/wiki/Cookbook%3AGrapefruit_and_Crab_Cocktail',
         'CC BY-SA 3.0'
  where not exists (
    select 1 from public.recipes where lower(title) = lower('Grapefruit and Crab Cocktail'))
  returning id
)
insert into public.recipe_ingredients (recipe_id, ingredient_id, role, quantity)
select ins.id, i.id, 'core', v.qty
from ins
join (values
  ('mayonnaise', '4 teaspoons'),
  ('lemon juice', '1 teaspoon'),
  ('parsley', NULL)
) as v(name, qty) on true
join public.ingredients i on lower(i.name) = v.name
on conflict (recipe_id, ingredient_id) do nothing;

with ins as (
  insert into public.recipes
    (title, instructions, cuisine, status, author_id,
     source_name, source_url, license)
  select 'Gravy Cakes (Hartshorne)', 'Chop 2 legs of beef in pieces, put them into a pot of water, and slow cook for 24 hours.
Add onions, herbs, and spices as for gravy.
Continue stewing until the meat is off the bones, and the gravy has started to develop.
Strain the mixture into a milk-pan, to which quantity it should be reduced.
When cold, skim off the fat, put it into a saucepan, and add any other flavourings as wanted.
Simmer it on a slow heat until reduced to about 12 saucers two-thirds full,
Put them in an airy place till as dry as leather, put them in paper bags, and keep in a dry place.',
         NULL, 'approved',
         (select id from public.profiles where role = 'admin'
          order by created_at limit 1),
         'Wikibooks Cookbook', 'https://en.wikibooks.org/wiki/Cookbook%3AGravy_Cakes_%28Hartshorne%29',
         'CC BY-SA 3.0'
  where not exists (
    select 1 from public.recipes where lower(title) = lower('Gravy Cakes (Hartshorne)'))
  returning id
)
insert into public.recipe_ingredients (recipe_id, ingredient_id, role, quantity)
select ins.id, i.id, 'core', v.qty
