  ('onions', '3')
) as v(name, qty) on true
join public.ingredients i on lower(i.name) = v.name
on conflict (recipe_id, ingredient_id) do nothing;

with ins as (
  insert into public.recipes
    (title, instructions, cuisine, status, author_id,
     source_name, source_url, license)
  select 'Green Spinach Food Coloring', 'Blanch the spinach by boiling in a large volume of water for 2 minutes (until bright green) then draining and quickly transferring to cold water. Let rest 1–2 minutes.
Drain the spinach and blend it to a purée with the ½ cup (125 ml) water.
Using a cheesecloth, strain the purée into a bowl to extract the juice.
Pour the juice into a pan and add sugar.
Turn the heat to medium-high, and stir to dissolve the sugar.
Skim off and discard any foam that collects at the surface of the liquid.
Turn the heat to high and boil until the liquid reduces to a single-thread consistency.
Turn off the heat and stir in the lemon juice.
Cool slightly, then pour into an airtight jar and cool completely.',
         NULL, 'approved',
         (select id from public.profiles where role = 'admin'
          order by created_at limit 1),
         'Wikibooks Cookbook', 'https://en.wikibooks.org/wiki/Cookbook%3AGreen_Spinach_Food_Coloring',
         'CC BY-SA 3.0'
  where not exists (
    select 1 from public.recipes where lower(title) = lower('Green Spinach Food Coloring'))
  returning id
)
insert into public.recipe_ingredients (recipe_id, ingredient_id, role, quantity)
select ins.id, i.id, 'core', v.qty
from ins
join (values
  ('spinach', '100 g'),
  ('water', NULL),
  ('sugar', '3 tablespoons'),
  ('lemon juice', NULL)
) as v(name, qty) on true
join public.ingredients i on lower(i.name) = v.name
on conflict (recipe_id, ingredient_id) do nothing;

